import json,glob
for fn in glob.glob('.sessions/*.jsonl'):
  lines=open(fn).readlines()
  for i,l in enumerate(lines):
    if 'check-refs' not in l: continue
    d=json.loads(l)
    m=d.get('message',{}); c=m.get('content')
    parts=[]
    if isinstance(c,str): parts=[c]
    else:
      for x in c if isinstance(c,list) else []:
        if isinstance(x,dict):
          if x.get('type')=='text': parts.append(x['text'])
          elif x.get('type')=='tool_use': parts.append(str(x.get('input'))[:400])
          elif x.get('type')=='tool_result': parts.append(str(x.get('content'))[:300])
